let user=null,data=null,current=null,dirty=false;
const $=id=>document.getElementById(id);const esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');
function clone(v){return JSON.parse(JSON.stringify(v))}function statusText(s){return s==='active'?'사용중':s==='locked'?'잠금':'작성중'}function halfText(h){return h==='first'?'상반기':'하반기'}
const api=(path,opt={})=>window.EHSApi.request(path,opt);
function goHome(){if(dirty&&!confirm('저장하지 않은 변경사항이 있습니다. 이동할까요?'))return;location.href='/home'}$('homeBtn').onclick=goHome;$('refreshBtn').onclick=()=>{if(dirty&&!confirm('저장하지 않은 변경사항이 있습니다. 새로고침할까요?'))return;load()};window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
function modal(title,body,actions=''){$('modalTitle').textContent=title;$('modalBody').innerHTML=body;$('modalActions').innerHTML=actions;$('modal').classList.remove('hidden')}function closeModal(){$('modal').classList.add('hidden')}$('modalClose').onclick=closeModal;$('modal').onclick=e=>{if(e.target===$('modal'))closeModal()};
function sortTemplates(list){const by={};for(const t of list||[]){(by[t.year]??=[]).push(t)}return Object.entries(by).sort((a,b)=>Number(b[0])-Number(a[0]))}
function renderList(){const html=sortTemplates(data?.templates||[]).map(([year,list])=>`<div class="tpl-year">${year}년</div>${list.map(t=>`<button class="tpl ${current?.id===t.id?'active':''}" data-id="${esc(t.id)}" type="button"><div class="tpl-main"><span class="tpl-name">${halfText(t.half)}${Number(t.version)>1?` v${t.version}`:''}</span></div><div class="tpl-meta">평가 ${Number(t.score_total||0)}점 · 가점 +${Number(t.bonus_total||0)}점</div></button>`).join('')}`).join('');$('templateList').innerHTML=html||'<div class="empty">평가표가 없습니다.</div>';$('templateList').querySelectorAll('.tpl').forEach(b=>b.onclick=()=>selectTemplate(b.dataset.id))}
function validationHtml(v){if(!v)return'';return `<div class="validation ${v.valid?'ok':'bad'}">${v.valid?'✓ 평가 시작 가능':'평가 시작 전 확인 필요'}${v.errors?.length?`<ul>${v.errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}</div>`}
function catChildren(parent){return (current.categories||[]).filter(c=>(c.parent_id||null)===(parent||null)).sort((a,b)=>Number(a.sort_order)-Number(b.sort_order))}
function itemsFor(catId){return (current.items||[]).filter(i=>i.category_id===catId).sort((a,b)=>Number(a.sort_order)-Number(b.sort_order))}
function guideButton(item){return (item.submission_guide||item.judgment_guide)?`<button class="info-btn" data-guide="${esc(item.id)}" type="button" title="가이드">i</button>`:''}
function itemHtml(item,index,list){return `<div class="item" data-item="${esc(item.id)}"><div class="order"><button data-move="up" ${index===0?'disabled':''}>▲</button><button data-move="down" ${index===list.length-1?'disabled':''}>▼</button></div><div class="item-name"><strong><span>${esc(item.item_name)}</span>${guideButton(item)}</strong><small>${esc(item.item_code||'')} ${item.na_rules?.length?`· N/A ${item.na_rules.length}개 조건`:''}</small></div><div class="score">${Number(item.max_score||0)}점</div><div class="type"><span class="tag ${item.item_type==='bonus'?'draft':'active-status'}">${item.item_type==='bonus'?'가점항목':'평가항목'}</span></div><div class="row-actions"><button class="mini" data-edit-item="${esc(item.id)}" title="수정">✎</button><button class="mini danger" data-delete-item="${esc(item.id)}" title="삭제">×</button></div></div>`}
function categoryBlock(cat,depth=0){const its=itemsFor(cat.id);const subs=catChildren(cat.id);return `<div class="category" data-cat="${esc(cat.id)}"><div class="category-head"><div class="cat-title"><b>${depth?'↳ ':''}${esc(cat.category_name)}</b></div><div class="cat-actions"><button class="mini" data-add-item="${esc(cat.id)}" title="평가항목 추가">＋</button>${depth===0?`<button class="mini" data-add-sub="${esc(cat.id)}" title="중분류 추가">⌘</button>`:''}<button class="mini" data-edit-cat="${esc(cat.id)}" title="수정">✎</button><button class="mini danger" data-delete-cat="${esc(cat.id)}" title="삭제">×</button></div></div><div class="items">${its.length?its.map((x,i)=>itemHtml(x,i,its)).join(''):'<div class="empty">평가항목이 없습니다.</div>'}</div>${subs.map(s=>categoryBlock(s,1)).join('')}</div>`}
function renderWorkspace(){if(!current){$('workspace').innerHTML='<div class="card"><div class="empty">평가표를 선택하세요.</div></div>';return}const v=data.validation||{valid:false,errors:[]};$('workspace').innerHTML=`<div class="page-head"><div><h1>${esc(current.name)}</h1><div class="meta">${current.year}년 ${halfText(current.half)} · 원본 평가표는 회차 운영 중에도 수정할 수 있습니다.${current.source_template_id?' · 이전 평가표 복사본':''}</div></div><div class="head-buttons"><button class="btn" id="settingsBtn">평가표 설정</button><button class="btn primary" id="saveBtn">변경사항 저장</button><button class="btn danger" id="deleteTplBtn">평가표 삭제</button></div></div><div class="summary"><div class="metric ${Number(v.score_total)===100?'ok':'bad'}"><span>평가항목 배점</span><b>${Number(v.score_total||0)} / 100</b></div><div class="metric"><span>가점항목 배점</span><b>+${Number(v.bonus_total||0)}</b></div><div class="metric"><span>평가항목 수</span><b>${(current.items||[]).filter(x=>x.item_type!=='bonus').length}</b></div><div class="metric"><span>가점항목 수</span><b>${(current.items||[]).filter(x=>x.item_type==='bonus').length}</b></div></div>${validationHtml(v)}<div class="grid"><section class="card"><div class="card-head"><strong>평가표 편집</strong><div class="card-actions"><button class="small-btn" id="addCatBtn">+ 대분류</button></div></div><div class="categories">${catChildren(null).map(c=>categoryBlock(c)).join('')||'<div class="empty">대분류를 추가하세요.</div>'}</div></section></div>`;bindWorkspace()}
function renderPolicy(){const p=data.policy||{};$('policyBox').innerHTML=`<div class="toggle-row"><span>익년도 상반기 평가 면제</span><input id="policyEnabled" type="checkbox" ${Number(p.first_half_exempt_enabled)!==0?'checked':''}></div><div class="policy-field"><label>면제 기준 i-PaSS 점수</label><input id="policyThreshold" type="number" min="0" max="100" step="0.1" value="${Number(p.excellence_threshold??90)}"></div><div class="policy-field"><label>면제 연도 하반기 평가 반영비율</label><input id="policySecondWeight" type="number" min="0" max="100" step="0.1" value="${Number(p.exempt_second_half_weight??80)}"></div><div class="policy-note">면제 협력사: 하반기 평가 80% + 협의체 10% + 산업재해 10%. 최종 i-PaSS는 100점을 초과하지 않습니다.</div><button class="btn primary" id="savePolicyBtn" style="width:100%;margin-top:12px">면제 설정 저장</button>`;$('savePolicyBtn').onclick=savePolicy}
function bindWorkspace(){
  $('addCatBtn')?.addEventListener('click',()=>editCategory());$('saveBtn')?.addEventListener('click',saveContent);$('settingsBtn')?.addEventListener('click',openTemplateSettings);$('deleteTplBtn')?.addEventListener('click',deleteTemplate);
  document.querySelectorAll('[data-add-sub]').forEach(b=>b.onclick=()=>editCategory(null,b.dataset.addSub));document.querySelectorAll('[data-edit-cat]').forEach(b=>b.onclick=()=>editCategory(b.dataset.editCat));document.querySelectorAll('[data-delete-cat]').forEach(b=>b.onclick=()=>deleteCategory(b.dataset.deleteCat));document.querySelectorAll('[data-add-item]').forEach(b=>b.onclick=()=>editItem(null,b.dataset.addItem));document.querySelectorAll('[data-edit-item]').forEach(b=>b.onclick=()=>editItem(b.dataset.editItem));document.querySelectorAll('[data-delete-item]').forEach(b=>b.onclick=()=>deleteItem(b.dataset.deleteItem));document.querySelectorAll('[data-guide]').forEach(b=>b.onclick=()=>showGuide(b.dataset.guide));document.querySelectorAll('.item [data-move]').forEach(b=>b.onclick=()=>moveItem(b.closest('.item').dataset.item,b.dataset.move));
}
function markDirty(){dirty=true;data.validation=localValidate();renderList();renderWorkspace()}
function localValidate(){const errors=[];let score=0,bonus=0;if(!(current.items||[]).length)errors.push('평가항목이 없습니다.');for(const i of current.items||[]){if(!String(i.item_name||'').trim())errors.push('평가항목명이 비어 있습니다.');if(!current.categories.some(c=>c.id===i.category_id))errors.push(`${i.item_name||'항목'}의 분류가 지정되지 않았습니다.`);if(i.item_type==='bonus')bonus+=Number(i.max_score||0);else score+=Number(i.max_score||0)}score=Math.round(score*100)/100;bonus=Math.round(bonus*100)/100;if(score!==100)errors.push(`평가 배점 합계가 ${score}점입니다. 100점이어야 합니다.`);return{valid:!errors.length,errors,score_total:score,bonus_total:bonus,final_score_cap:100}}
function editCategory(id=null,parentId=null){if(current.status!=='draft')return;const c=id?current.categories.find(x=>x.id===id):null;modal(c?'분류 수정':parentId?'중분류 추가':'대분류 추가',`<div class="field"><label>${parentId?'중분류명':'대분류명'}</label><input id="catName" value="${esc(c?.category_name||'')}"></div>`,`<button class="btn" id="cancelModal">취소</button><button class="btn primary" id="saveCat">저장</button>`);$('cancelModal').onclick=closeModal;$('saveCat').onclick=()=>{const name=$('catName').value.trim();if(!name)return alert('분류명을 입력하세요.');if(c)c.category_name=name;else current.categories.push({id:'local-cat-'+crypto.randomUUID(),template_id:current.id,parent_id:parentId||null,category_name:name,sort_order:current.categories.filter(x=>(x.parent_id||null)===(parentId||null)).length});closeModal();markDirty()}}
function deleteCategory(id){if(!confirm('분류와 포함된 평가항목을 삭제할까요?'))return;const children=new Set([id,...current.categories.filter(c=>c.parent_id===id).map(c=>c.id)]);current.categories=current.categories.filter(c=>!children.has(c.id));current.items=current.items.filter(i=>!children.has(i.category_id));markDirty()}
function naRowsHtml(rules=[]){return (rules||[]).map((r,i)=>`<div class="na-row"><select class="naType"><option value="worker_count" ${r.rule_type==='worker_count'?'selected':''}>근로자수</option><option value="industry_worker" ${r.rule_type==='industry_worker'?'selected':''}>업종 × 근로자수</option></select><input class="naIndustry" placeholder="업종명" value="${esc(r.industry_name||'')}"><input class="naWorkers" type="number" min="0" placeholder="기준 인원" value="${Number(r.min_worker_count||0)}"><button class="mini danger naRemove" type="button">×</button></div>`).join('')}
function editItem(id=null,catId=null){if(current.status!=='draft')return;const item=id?current.items.find(x=>x.id===id):null;const cats=current.categories.map(c=>`<option value="${esc(c.id)}" ${(item?.category_id||catId)===c.id?'selected':''}>${c.parent_id?'↳ ':''}${esc(c.category_name)}</option>`).join('');modal(item?'평가항목 수정':'평가항목 추가',`<div class="form-grid"><div class="field"><label>구분</label><select id="itemType"><option value="score" ${item?.item_type!=='bonus'?'selected':''}>평가항목</option><option value="bonus" ${item?.item_type==='bonus'?'selected':''}>가점항목</option></select></div><div class="field"><label>배점</label><input id="itemScore" type="number" min="0" step="0.1" value="${Number(item?.max_score||0)}"></div><div class="field"><label>분류</label><select id="itemCat">${cats}</select></div><div class="field"><label>항목 번호</label><input id="itemCode" value="${esc(item?.item_code||'')}"></div><div class="field full"><label>평가항목명</label><input id="itemName" value="${esc(item?.item_name||'')}"></div><div class="field full"><label>판정기준</label><textarea id="judgmentGuide">${esc(item?.judgment_guide||'')}</textarea></div><div class="field full"><label>제출가이드</label><textarea id="submissionGuide">${esc(item?.submission_guide||'')}</textarea></div></div><div class="na-box"><div class="na-title"><strong>N/A 조건</strong><button class="small-btn" id="addNa" type="button">+ 조건</button></div><div id="naRows">${naRowsHtml(item?.na_rules||[])}</div></div>`,`<button class="btn" id="cancelModal">취소</button><button class="btn primary" id="saveItem">저장</button>`);$('cancelModal').onclick=closeModal;bindNa();$('addNa').onclick=()=>{$('naRows').insertAdjacentHTML('beforeend',naRowsHtml([{rule_type:'worker_count',min_worker_count:5}]));bindNa()};$('saveItem').onclick=()=>{const name=$('itemName').value.trim(),score=Number($('itemScore').value);if(!name)return alert('평가항목명을 입력하세요.');if(!Number.isFinite(score)||score<0)return alert('배점을 확인하세요.');const rules=[...$('naRows').querySelectorAll('.na-row')].map(r=>({rule_type:r.querySelector('.naType').value,industry_name:r.querySelector('.naIndustry').value.trim()||null,min_worker_count:Math.max(0,Math.round(Number(r.querySelector('.naWorkers').value)||0))}));const next={id:item?.id||'local-item-'+crypto.randomUUID(),template_id:current.id,category_id:$('itemCat').value,item_code:$('itemCode').value.trim()||null,item_name:name,item_type:$('itemType').value,max_score:score,judgment_guide:$('judgmentGuide').value.trim()||null,submission_guide:$('submissionGuide').value.trim()||null,sort_order:item?.sort_order??current.items.length,na_rules:rules};if(item)Object.assign(item,next);else current.items.push(next);closeModal();markDirty()}}
function bindNa(){$('naRows').querySelectorAll('.na-row').forEach(r=>{const sync=()=>{const industry=r.querySelector('.naIndustry');industry.disabled=r.querySelector('.naType').value!=='industry_worker';if(industry.disabled)industry.value=''};r.querySelector('.naType').onchange=sync;r.querySelector('.naRemove').onclick=()=>r.remove();sync()})}
function deleteItem(id){if(!confirm('평가항목을 삭제할까요?'))return;current.items=current.items.filter(i=>i.id!==id);markDirty()}
function moveItem(id,dir){const item=current.items.find(x=>x.id===id);if(!item)return;const list=itemsFor(item.category_id),idx=list.findIndex(x=>x.id===id),j=dir==='up'?idx-1:idx+1;if(j<0||j>=list.length)return;const a=list[idx],b=list[j],tmp=a.sort_order;a.sort_order=b.sort_order;b.sort_order=tmp;markDirty()}
function showGuide(id){const item=current.items.find(x=>x.id===id);modal(item.item_name,`<div class="guide-view"><b>제출가이드</b>\n${esc(item.submission_guide||'등록된 제출가이드가 없습니다.')}\n\n<b>판정기준</b>\n${esc(item.judgment_guide||'등록된 판정기준이 없습니다.')}</div>`,`<button class="btn" id="closeGuide">닫기</button>`);$('closeGuide').onclick=closeModal}
async function saveContent(){try{const payload={categories:current.categories.map((c,i)=>({...c,sort_order:Number(c.sort_order??i)})),items:current.items.map((x,i)=>({...x,sort_order:Number(x.sort_order??i)}))};const d=await api(`/api/admin/evaluation-management/templates/${encodeURIComponent(current.id)}/content`,{method:'PUT',body:JSON.stringify(payload)});current=d.template;data.validation=d.validation;dirty=false;await refreshBundle(current.id)}catch(e){alert(e.message)}}
async function changeStatus(status){if(status==='active'&&!localValidate().valid)return alert(localValidate().errors.join('\n'));const msg=status==='active'?'이 평가표를 사용 시작할까요? 사용 시작 후 항목 구조는 수정할 수 없습니다.':'평가를 종료하고 평가표를 잠글까요?';if(!confirm(msg))return;try{await api(`/api/admin/evaluation-management/templates/${encodeURIComponent(current.id)}`,{method:'PATCH',body:JSON.stringify({status})});dirty=false;await refreshBundle(current.id)}catch(e){alert(e.data?.validation?.errors?.join('\n')||e.message)}}
async function deleteTemplate(){if(!confirm('작성중 평가표를 삭제할까요?'))return;try{await api(`/api/admin/evaluation-management/templates/${encodeURIComponent(current.id)}`,{method:'DELETE'});dirty=false;await load()}catch(e){alert(e.message)}}
function settingNumber(id){return Number($(id).value)}
function openTemplateSettings(){if(!current)return;const s=current.settings||{};modal('평가표 설정',`<div class="setting-section"><h4>평가 컨셉</h4><div class="field"><textarea id="setConcept" placeholder="이번 평가에서 중점적으로 확인할 내용을 입력하세요.">${esc(s.concept_text||'')}</textarea></div></div><div class="setting-section"><h4>협력사 등급 기준</h4><div class="form-grid"><div class="field"><label>안전관리 우수협력사 최저점</label><input id="setExcellent" type="number" min="1" max="100" value="${Number(s.excellent_min??90)}"></div><div class="field"><label>적격 협력사 최저점</label><input id="setQualified" type="number" min="0" max="99" value="${Number(s.qualified_min??70)}"></div></div><div class="grade-preview"><div class="good"><b>안전관리 우수협력사</b><span id="gradeExcellent">90점 이상</span></div><div class="fit"><b>적격 협력사</b><span id="gradeQualified">70점 이상</span></div><div class="grow"><b>역량 강화 협력사</b><span id="gradeGrow">70점 미만</span></div></div></div><div class="setting-section"><h4>상반기 면제</h4><div class="toggle-row"><span>전년도 우수협력사 상반기 면제</span><input id="setExemptEnabled" type="checkbox" ${Number(s.first_half_exempt_enabled)!==0?'checked':''}></div><div class="form-grid"><div class="field"><label>면제 기준 점수</label><input id="setExemption" type="number" min="0" max="100" value="${Number(s.exemption_threshold??90)}"></div><div class="field"><label>면제 시 하반기 반영</label><input id="setExemptSecond" type="number" min="0" max="100" value="${Number(s.exempt_second_half_weight??80)}"></div></div></div><div class="setting-section"><h4>점수 반영 비율</h4><div class="form-grid"><div class="field"><label>상반기 평가</label><input id="setFirstWeight" type="number" value="${Number(s.normal_first_half_weight??40)}"></div><div class="field"><label>하반기 평가</label><input id="setSecondWeight" type="number" value="${Number(s.normal_second_half_weight??40)}"></div><div class="field"><label>협의체 참석</label><input id="setCommittee" type="number" value="${Number(s.committee_weight??10)}"></div><div class="field"><label>산업재해</label><input id="setAccident" type="number" value="${Number(s.industrial_accident_weight??10)}"></div></div><p class="setting-help">일반 평가 반영 합계와 면제 평가 반영 합계는 각각 100점이어야 합니다. 이 설정은 새 회차 생성 시 복사되어 회차별로 보존됩니다.</p></div>`,`<button class="btn" id="cancelModal">취소</button><button class="btn primary" id="saveSettings">설정 저장</button>`);$('cancelModal').onclick=closeModal;const sync=()=>{const e=settingNumber('setExcellent'),q=settingNumber('setQualified');$('gradeExcellent').textContent=`${e}점 이상`;$('gradeQualified').textContent=`${q}점 이상 ${e}점 미만`;$('gradeGrow').textContent=`${q}점 미만`};$('setExcellent').oninput=sync;$('setQualified').oninput=sync;sync();$('saveSettings').onclick=saveTemplateSettings}
async function saveTemplateSettings(){const settings={concept_text:$('setConcept').value.trim(),excellent_min:settingNumber('setExcellent'),qualified_min:settingNumber('setQualified'),first_half_exempt_enabled:$('setExemptEnabled').checked,exemption_threshold:settingNumber('setExemption'),normal_first_half_weight:settingNumber('setFirstWeight'),normal_second_half_weight:settingNumber('setSecondWeight'),exempt_second_half_weight:settingNumber('setExemptSecond'),committee_weight:settingNumber('setCommittee'),industrial_accident_weight:settingNumber('setAccident')};try{const d=await api(`/api/admin/evaluation-management/templates/${encodeURIComponent(current.id)}/settings`,{method:'PATCH',body:JSON.stringify(settings)});current.settings=d.settings;closeModal();await refreshBundle(current.id)}catch(e){alert(e.message)}}
function createTemplate(copy=false){if(dirty&&!confirm('저장하지 않은 변경사항이 있습니다. 계속할까요?'))return;const now=new Date().getFullYear(),templates=data.templates||[];modal(copy?'이전 평가표 복사':'새 평가표',`<div class="setting-section"><h4>평가 연도</h4><div class="choice-grid" id="yearChoices">${[now,now+1].map((y,i)=>`<button class="choice ${i===0?'selected':''}" data-value="${y}" type="button">${y}년</button>`).join('')}</div></div><div class="setting-section"><h4>평가 시기</h4><div class="choice-grid" id="halfChoices"><button class="choice selected" data-value="first" type="button">상반기<small>1월~6월 평가</small></button><button class="choice" data-value="second" type="button">하반기<small>7월~12월 평가</small></button></div></div>${copy?`<div class="setting-section"><h4>복사할 평가표</h4><div class="choice-grid" id="sourceChoices">${templates.map((t,i)=>`<button class="choice ${i===0?'selected':''}" data-value="${esc(t.id)}" type="button">${t.year}년 ${halfText(t.half)}<small>${esc(t.name)}</small></button>`).join('')}</div></div>`:''}`,`<button class="btn" id="cancelModal">취소</button><button class="btn primary" id="createTemplateConfirm">${copy?'복사':'만들기'}</button>`);$('cancelModal').onclick=closeModal;for(const id of ['yearChoices','halfChoices','sourceChoices'])$(id)?.querySelectorAll('.choice').forEach(b=>b.onclick=()=>{b.parentElement.querySelectorAll('.choice').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')});$('createTemplateConfirm').onclick=async()=>{const year=Number($('yearChoices').querySelector('.selected').dataset.value),half=$('halfChoices').querySelector('.selected').dataset.value,source=$('sourceChoices')?.querySelector('.selected')?.dataset.value||null;try{const d=await api('/api/admin/evaluation-management/templates',{method:'POST',body:JSON.stringify({year,half,source_template_id:source})});closeModal();dirty=false;await refreshBundle(d.id)}catch(e){alert(e.message)}}}
$('newBlankBtn').onclick=()=>createTemplate(false);$('copyBtn').onclick=()=>createTemplate(true);$('policyJump').onclick=openTemplateSettings;
async function savePolicy(){try{const d=await api('/api/admin/evaluation-management/policy',{method:'PATCH',body:JSON.stringify({excellence_threshold:Number($('policyThreshold').value),first_half_exempt_enabled:$('policyEnabled').checked,exempt_second_half_weight:Number($('policySecondWeight').value)})});data.policy=d.policy;renderPolicy();alert('저장했습니다.')}catch(e){alert(e.message)}}
async function previewExemptions(){const y=Number($('previewYear').value);$('exemptList').innerHTML='<div class="exempt-empty">조회 중...</div>';try{const d=await api(`/api/admin/evaluation-management/exemptions?year=${encodeURIComponent(y)}`);$('exemptList').innerHTML=d.companies.length?`<div class="exempt-list">${d.companies.map(c=>`<div class="exempt-row"><span>${esc(c.company_name)}</span><b>${c.previous_ipass_score}점</b></div>`).join('')}</div>`:'<div class="exempt-empty">면제 예상 협력사가 없습니다.</div>'}catch(e){$('exemptList').innerHTML=`<div class="exempt-empty">${esc(e.message)}</div>`}}
async function selectTemplate(id){if(dirty&&!confirm('저장하지 않은 변경사항이 있습니다. 이동할까요?'))return;dirty=false;await refreshBundle(id)}
async function refreshBundle(id){$('workspace').innerHTML='<div class="loading">불러오는 중...</div>';const d=await api(`/api/admin/evaluation-management${id?`?template_id=${encodeURIComponent(id)}`:''}`);data=d;current=d.template?clone(d.template):null;if(current)current.status='draft';renderList();renderWorkspace()}
async function load(){dirty=false;try{user=await window.EHSAuth.requireUser({role:'admin'});$('userLabel').textContent=user.name||user.email||'';await refreshBundle()}catch(e){if(e?.status===401)return;$('workspace').innerHTML=`<div class="card"><div class="empty">${esc(window.EHSApi.describe(e))}</div></div>`}}
load();
